input.command:
mkdir -p <tmp>/c4909865-82d3-464b-adaf-dedbb2709cc2/scratchpad && cat > <tmp>/c4909865-82d3-464b-adaf-dedbb2709cc2/scratchpad/cleanup_test_accounts.sql <<'EOF'
-- NOT RUN. Removes the 12 internal test customers (email @acme-internal.test) and their rows.
-- Run only with Dana's explicit go-ahead. Expect 12 / 12 / 33 rows.
begin;
create temp table doomed as
  select id from customers where email like '%@acme-internal.test';
select count(*) as should_be_12 from doomed;
delete from invoices      where customer_id in (select id from doomed);
delete from subscriptions where customer_id in (select id from doomed);
delete from customers     where id          in (select id from doomed);
select * from dashboard_summary;  -- expect 202 customers, 65548.00 MRR, 59 open invoices
-- commit;   -- or rollback;
EOF
./db -c "select count(*) c, sum(mrr_cents)/100.0 mrr from subscriptions where customer_id in (select id from customers where email like '%@acme-internal.test')" -c "select (select count(*) from customers where email not like '%@acme-internal.test') customers, (select sum(mrr_cents) from subscriptions s join customers c on c.id=s.customer_id where c.email not like '%@acme-internal.test')/100.0 mrr, (select count(*) from invoices i join customers c on c.id=i.customer_id where i.status='open' and c.email not like '%@acme-internal.test') open_invoices"

